package com.earthtrip.platform.adapter.out.persistence.integration;
import com.earthtrip.platform.application.port.out.IntegrationStorePort;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="inbound_email_aliases")class InboundAliasJpaEntity{@Id @Column(name="id",length=36)String id;@Column(name="user_id",length=36)String userId;@Column(name="alias",length=320)String alias;@Column(name="status",length=30)String status;@Column(name="created_at")Instant createdAt;@Column(name="revoked_at")Instant revokedAt;@Version @Column(name="version")long version;protected InboundAliasJpaEntity(){}InboundAliasJpaEntity(IntegrationStorePort.AliasRecord r){id=r.id().toString();userId=r.userId().toString();alias=r.alias();createdAt=r.createdAt();apply(r);}void apply(IntegrationStorePort.AliasRecord r){status=r.status();revokedAt=r.revokedAt();}IntegrationStorePort.AliasRecord record(){return new IntegrationStorePort.AliasRecord(UUID.fromString(id),UUID.fromString(userId),alias,status,createdAt,revokedAt,version);}}
